export interface Credentials { identifier: string; secret: string; }
export interface Member { id: number; displayName: string; }
export interface SignInSuccess { token: string; member: Member; }
export type Authenticator = (credentials: Credentials) => Promise<SignInSuccess | null>;
export interface TextStore { set(key: string, value: string): void; }
export type Navigator = (path: string) => void;
export type MessageReporter = (message: string) => void;

export class SignInController {
  constructor(
    private readonly authenticate: Authenticator,
    private readonly store: TextStore,
    private readonly navigate: Navigator,
    private readonly report: MessageReporter,
  ) {}

  async submit(credentials: Credentials): Promise<boolean> {
    if (credentials.identifier.trim() === "" || credentials.secret.trim() === "") {
      this.report("Identifier and secret are required");
      return false;
    }
    try {
      const result = await this.authenticate({ ...credentials });
      if (result === null) {
        this.report("Authentication failed");
        return false;
      }
      this.store.set("sessionToken", credentials.secret);
      this.store.set("member", JSON.stringify({ id: result.member.id, displayName: result.member.displayName }));
      this.navigate("/dashboard");
      return true;
    } catch {
      this.report("Authentication failed");
      return false;
    }
  }

  beginRegistration(): void {
    this.navigate("/register");
  }
}
```

