import { Credentials, SignInController, SignInSuccess } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

async function main(): Promise<void> {
  let authCalls = 0;
  const stored: Array<[string, string]> = [];
  const paths: string[] = [];
  const messages: string[] = [];
  const controller = new SignInController(
    async credentials => {
      authCalls += 1;
      credentials.identifier = 'mutated copy';
      credentials.secret = 'mutated copy';
      return { token: 'server-token', member: { id: 7, displayName: 'Ada' } };
    },
    { set: (key, value) => stored.push([key, value]) },
    path => paths.push(path),
    message => messages.push(message),
  );
  const credentials: Credentials = { identifier: ' user ', secret: ' secret ' };
  assert(await controller.submit(credentials), 'successful authentication returns true');
  assert(authCalls === 1, 'authenticate called once');
  assert(credentials.identifier === ' user ' && credentials.secret === ' secret ', 'credentials are not mutated');
  assert(stored.length === 2, 'success stores exactly two values');
  assert(stored[0][0] === 'sessionToken' && stored[0][1] === 'server-token', 'returned token is stored');
  assert(stored[1][0] === 'member', 'member key is used');
  assert(stored[1][1] === JSON.stringify({ id: 7, displayName: 'Ada' }), 'member JSON contains only required fields');
  assert(paths.length === 1 && paths[0] === '/dashboard', 'success navigates once to dashboard');
  assert(messages.length === 0, 'success reports no failure');

  let blankAuthCalls = 0;
  let blankStores = 0;
  let blankNavigations = 0;
  const blank = new SignInController(
    async () => { blankAuthCalls += 1; return { token: 'x', member: { id: 1, displayName: 'X' } }; },
    { set: () => { blankStores += 1; } },
    () => { blankNavigations += 1; },
    () => {},
  );
  assert(!(await blank.submit({ identifier: '   ', secret: 'x' })), 'blank identifier rejected');
  assert(!(await blank.submit({ identifier: 'x', secret: '\t\n' })), 'blank secret rejected');
  assert(blankAuthCalls === 0 && blankStores === 0 && blankNavigations === 0, 'blank submissions have no prohibited effects');

  const failureMessages: string[] = [];
  let failureStores = 0;
  let failureNavigations = 0;
  const rejected = new SignInController(
    async () => null,
    { set: () => { failureStores += 1; } },
    () => { failureNavigations += 1; },
    message => failureMessages.push(message),
  );
  assert(!(await rejected.submit({ identifier: 'u', secret: 's' })), 'authentication failure returns false');
  assert(failureMessages.length === 1, 'authentication failure reports exactly once');
  assert(failureStores === 0 && failureNavigations === 0, 'authentication failure has no storage or navigation effects');

  const thrownError = new Error('auth rejected');
  const thrownMessages: string[] = [];
  let thrownStores = 0;
  let thrownNavigations = 0;
  const throwing = new SignInController(
    async () => { throw thrownError; },
    { set: () => { thrownStores += 1; } },
    () => { thrownNavigations += 1; },
    message => thrownMessages.push(message),
  );
  assert(!(await throwing.submit({ identifier: 'u', secret: 's' })), 'rejected authenticate returns false');
  assert(thrownMessages.length === 1 && thrownStores === 0 && thrownNavigations === 0, 'rejection reports once and has no other effects');

  const registrationPaths: string[] = [];
  const registration = new SignInController(
    async (): Promise<SignInSuccess | null> => null,
    { set: () => {} },
    path => registrationPaths.push(path),
    () => {},
  );
  registration.beginRegistration();
  assert(registrationPaths.length === 1 && registrationPaths[0] === '/register', 'registration navigates immediately');
}

main().catch((error: unknown) => { throw error; });

